(window.webpackJsonp=window.webpackJsonp||[]).push([[166],{638:function(a,t,r){"use strict";r.r(t);var v=r(7),_=Object(v.a)({},(function(){var a=this,t=a.$createElement,r=a._self._c||t;return r("ContentSlotsDistributor",{attrs:{"slot-key":a.$parent.slotKey}},[r("p",[a._v("今晚开一个午餐肉罐头，锡钥匙拧断了，最后是拿勺柄撬开的。撬到一半我突然意识到一个时间线问题：罐头是 1810 年的发明，那专职开它的工具呢？答案是 1858 年。罐头在货架上等了将近半个世纪，才等来自己的开罐器。更离谱的是「罐头为什么能吃」这个问题本身——要等到 1861 年巴斯德的鹅颈瓶实验才有人给出答案。也就是说，人类先把罐头造出来、吃了五十多年，然后才知道它为什么不坏。")]),a._v(" "),r("p",[r("img",{attrs:{src:"/images/2026/11/07/cover-canned-food.jpeg",alt:"十九世纪的手工铁皮罐头，和一把凿子一把锤子——这就是最早的使用说明",loading:"lazy"}})]),a._v(" "),r("h2",{attrs:{id:"一、1795-年的悬赏-炮弹杀不了那么多士兵"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#一、1795-年的悬赏-炮弹杀不了那么多士兵"}},[a._v("#")]),a._v(" 一、1795 年的悬赏：炮弹杀不了那么多士兵")]),a._v(" "),r("p",[a._v("把时钟拨回拿破仑战争。当时欧洲各国军需官面对的是同一道算术题：一支远征军里，死于坏血病、痢疾和食物腐败的人，通常远多于阵亡的。军队需要的不是更多粮食，而是把粮食完好地运到战场的方法。1795 年，法国政府悬赏 12000 法郎，公开征集大规模保存食物的办法。这笔钱一挂就是十五年。")]),a._v(" "),r("p",[a._v("接榜的是一个五十多岁的糖果匠，尼古拉·阿佩尔（Nicolas Appert）。他的履历和化学不沾边：厨师、酿酒师、糖果匠，开过一家小作坊。他不明白食物为什么会坏，也没有任何一个同时代的人明白——当时的主流解释是「食物腐败是因为失去了某种活力」。阿佩尔只管试。他把食物装进玻璃瓶，塞紧软木塞，用铁丝把塞子扎死，整瓶扔进沸水煮上几个小时，出锅再用蜡封口。同样的流程，他试了十四年，肉、豌豆、牛奶、鸡汤，一样一样来。")]),a._v(" "),r("p",[a._v("1810 年 1 月，官方验收：他用这套流程保存了几个月的豌豆和牛肉，开瓶后一切完好。阿佩尔领走 12000 法郎，条件是把工艺全部公开出版——《长期保存各类动植物物质的艺术》当年出版，没有专利，全欧洲谁都可以照着做。这是法国政府的方法论：买断，而不是保护。")]),a._v(" "),r("p",[a._v("阿佩尔自己给这套工艺找的理由是：腐败的元凶是空气里的「氧」，所以要加热排出空气，再隔绝空气。理由是错的，操作歪打正着——真正起作用的，是煮沸把微生物杀死了，密封让新的微生物进不来。这个正确的答案还要等五十一年，等巴斯德把空气里的微生物装进鹅颈瓶里一个一个指认出来。")]),a._v(" "),r("p",[r("img",{attrs:{src:"/images/2026/11/07/fig-appert.jpeg",alt:"阿佩尔的作坊：玻璃瓶、软木塞和一锅沸水，1795 年的「无菌工艺」，理由却是错的",loading:"lazy"}})]),a._v(" "),r("h2",{attrs:{id:"二、从玻璃瓶到铁罐"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#二、从玻璃瓶到铁罐"}},[a._v("#")]),a._v(" 二、从玻璃瓶到铁罐")]),a._v(" "),r("p",[a._v("玻璃瓶军队带不动——会碎，也垒不了几层。1810 年 8 月，英国商人彼得·杜兰德（Peter Durand）拿到英国专利 3372 号，把阿佩尔的工艺搬进了镀锡铁皮罐。专利文书里玻璃瓶和铁罐都写了，但所有人都看得出铁罐才是未来：不怕摔，能堆码，比玻璃轻。1812 年专利转手给工程师布莱恩·唐金（Bryan Donkin），1813 年唐金在伦敦 Bermondsey 开出了世界上第一家罐头厂，同年给皇家海军试供了一批罐装炖牛肉——水兵们吃上了存放一年的肉，而且没人生病。")]),a._v(" "),r("p",[a._v("探险队是最早的大客户。1824 年帕里（Parry）的北极探险队整船装着罐头出发，还指望里面的蔬菜防坏血病——他们不知道维生素 C 在高温工序里早就死光了，这个 bug 要再等一百年才有人发现。")]),a._v(" "),r("p",[r("img",{attrs:{src:"/images/2026/11/07/fig-cannery.jpeg",alt:"世界第一家罐头厂的价目单与实验报告，约 1813 年：罐装炖牛肉每磅两先令六便士，附一封牙买加航程 14 天后开罐「完好如初」的客户信",loading:"lazy"}})]),a._v(" "),r("p",[a._v("这批罐子今天在博物馆里还能见到，厚得离谱：铁皮接近三毫米，纯手工敲出来的，一个罐子的皮常常比里面的肉还沉。罐身的使用说明不是拉环，是一把凿子和一把锤子——「沿罐边凿开」。所以开头那个问题的答案就在这里：头五十年吃罐头的人，用凿子、锤子、刺刀、石头，什么都用。军队的官方开罐工具就是刺刀。")]),a._v(" "),r("h2",{attrs:{id:"三、48-年里-为什么没人发明开罐器"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#三、48-年里-为什么没人发明开罐器"}},[a._v("#")]),a._v(" 三、48 年里，为什么没人发明开罐器")]),a._v(" "),r("p",[a._v("不是没人想到，是没人需要。头五十年，罐头是军需品和探险品，手工敲出来，量小、价高，全世界吃罐头的人口基数撑不起一个专门工具的市场。发明史里这个时差反复出现：产品发明解决「能不能」，工具发明解决「顺不顺手」，而后者只有等产量上来才轮得到。")]),a._v(" "),r("p",[a._v("转机还是战争——这次是标准化的战争。1858 年 2 月 5 日，康涅狄格州沃特伯里（Waterbury，黄铜之城）的埃兹拉·沃纳（Ezra Warner）拿到美国专利 20,898 号：一根杠杆加一片弯刀，后人叫它「刺刀式」开罐器。这是第一把专职开罐器，离罐头诞生过去了 48 年。美国内战期间它大批量发给北军，随后罐头第一次作为平民食品走进杂货店。")]),a._v(" "),r("p",[a._v("士兵对它的评价很差。弯刀会把金属屑崩进罐里，费力，还容易伤手，许多人宁可继续用刺刀。杂货店干脆把它锁在柜台上，由店员代开——开完一次，刀片常常直接报废。今天的沃特伯里博物馆里还躺着一把。")]),a._v(" "),r("p",[a._v("后面就是工具追平产品的几十年：1866 年奥斯特豪特（Osterhoudt）的「锡钥匙」——罐身上铆一把小钥匙，卷着卷边拧开，今天午餐肉和沙丁鱼罐头还在用这个结构；1870 年莱曼（Lyman）的切割轮加固定尖针，是现代转轮开罐器的祖先；1925 年，Star Can Opener 公司给切割轮配上夹住罐沿的齿轮底座，今天厨房抽屉里那种开罐器到这一步才定型。从罐头到「顺手的开罐器」，一共走了 115 年。")]),a._v(" "),r("p",[r("img",{attrs:{src:"/images/2026/11/07/fig-warner.jpeg",alt:"二十世纪中叶流行过的几款折叠开罐器：在转轮式定型之前，工具试过了几十种形状",loading:"lazy"}})]),a._v(" "),r("h2",{attrs:{id:"四、技术先行的账单-富兰克林船上的铅"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#四、技术先行的账单-富兰克林船上的铅"}},[a._v("#")]),a._v(" 四、技术先行的账单：富兰克林船上的铅")]),a._v(" "),r("p",[a._v("「先有产品，后有原理」的时差，留下过一笔沉重的账。1845 年，约翰·富兰克林爵士率 129 人寻找西北航道，全队无一生还。一个多世纪后的 1984 年，考古学家欧文·比蒂（Owen Beattie）掘出停尸岛上冻土中的船员遗体，头发和指甲里的铅浓度高得惊人。一个被广泛讨论的假说指向了罐头：早期罐头用铅锡焊料封缝，铅在长年存放中渗进食物。这个假说至今仍有争议——船上的淡水系统和其他铅来源同样可疑，但学界的主流看法是，铅中毒至少参与了对这 129 人的处决。工艺比理论先行了五十一年，中间有几笔是要还的。")]),a._v(" "),r("p",[a._v("发明者本人也没有等到红利。1814 年，反法同盟的普鲁士军队烧了阿佩尔在马西（Massy）的工厂；他把奖金投进重建，随后破产，1841 年九十一岁死于贫困。他活着的最后三十年里，罐头已经在喂全欧洲的军队和探险队。")]),a._v(" "),r("p",[r("img",{attrs:{src:"/images/2026/11/07/fig-franklin.jpeg",alt:"1845 年的西北航道：129 个人、一批铅焊料封口的罐头，和一场没人能返航的冬天",loading:"lazy"}})]),a._v(" "),r("h2",{attrs:{id:"五、易拉罐-同一个时差又来了一遍"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#五、易拉罐-同一个时差又来了一遍"}},[a._v("#")]),a._v(" 五、易拉罐：同一个时差又来了一遍")]),a._v(" "),r("p",[a._v("二十世纪，这个模式原样又跑了一遍。1935 年 1 月 24 日，美国克鲁格（Krueger）啤酒公司在弗吉尼亚州里士满第一次把啤酒灌进平顶金属罐上架，顺带诞生了一个粗糙的小工具：一块冲出三角形孔的铁片，绰号「church key」。买酒的人得随身带一片铁皮，啤酒才喝得上。")]),a._v(" "),r("p",[a._v("1959 年的一天，俄亥俄州代顿的厄莫尔·弗雷兹（Ermal Fraze）在汽车餐厅买啤酒，发现没带开罐器。他看着窗口的服务员把罐子按在车头保险杠的冲压具上硬顶开。回家路上他想：为什么开罐的功能要单独做一个工具？它不能长在罐子上吗？1963 年他拿到专利（US 3,349,751）：拉环，一拉就开，不用随身带任何东西。")]),a._v(" "),r("p",[a._v("然后历史重演：拉环解决了喝的问题，立刻制造了新问题。它是一次性的，被随手扔在沙滩和草地上，割伤脚，扎进海龟的鼻孔和鸟的胃，成了六十年代末美国环保叙事的标志物。1975 年，雷诺兹金属公司的丹尼尔·库兹克（Daniel Cudzik）拿出保留式拉环（stay-on tab，US 3,969,617）：拉环拉起后不再脱离罐身，就是今天全世界在用的那种。从「罐能装酒」到「罐能优雅地打开自己」，又是四十年。")]),a._v(" "),r("p",[r("img",{attrs:{src:"/images/2026/11/07/fig-pulltab.jpeg",alt:"1960 年代初的日常：开一罐啤酒要靠一把 church key——拉环发明前夜",loading:"lazy"}})]),a._v(" "),r("h2",{attrs:{id:"六、1865-年的罐头-1974-年开盖"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#六、1865-年的罐头-1974-年开盖"}},[a._v("#")]),a._v(" 六、1865 年的罐头，1974 年开盖")]),a._v(" "),r("p",[a._v("最后说一个硬核检验。1865 年 4 月 1 日，蒸汽船「伯特兰号」（Bertrand）在密苏里河沉没，船货里有一批罐头：桃子、牡蛎、番茄、樱桃白兰地。1968 年沉船被打捞，1974 年，美国国家食品加工者协会（NFPA）对这些一百零九岁的罐头做了检测：微生物学上安全，能吃。风味和维生素就别提了，但「罐头能吃」这件事在封罐后一百零九年依然成立——而给出这个答案的科学（微生物致腐），比罐头本身晚了半个世纪才出现。")]),a._v(" "),r("h2",{attrs:{id:"尾声"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#尾声"}},[a._v("#")]),a._v(" 尾声")]),a._v(" "),r("p",[a._v("把三个时差摆在一起看：")]),a._v(" "),r("ul",[r("li",[r("strong",[a._v("工艺 → 原理")]),a._v("：1810 年罐头已经能吃，1861 年才知道它为什么能吃，差 51 年")]),a._v(" "),r("li",[r("strong",[a._v("产品 → 工具")]),a._v("：1810 年有了罐头，1858 年才有开罐器，差 48 年")]),a._v(" "),r("li",[r("strong",[a._v("麻烦 → 新发明")]),a._v("：1858 年能开罐了，1963 年拉环才让开罐不疼，差 105 年")])]),a._v(" "),r("p",[a._v("没有一个环节是在正确的理论指导下诞生的。阿佩尔不知道微生物，杜兰德不知道铅焊料的代价，弗雷兹只是丢了自己的开罐器。技术的历史大多如此：先有一个歪打正着的动作，再用几十年搞清楚它为什么行，最后花几十年把它做得顺手。今天你拧不开瓶盖、顺手拿勺柄去撬的动作，和 1813 年用凿子对付铁罐的水兵，隔着两百一十三年，是同一个动作。")])])}),[],!1,null,null,null);t.default=_.exports}}]);